# === VERIFY ===
BANNED = ["לסיכום","ראשית","שנית","בנוסף לכך","יתרה מזאת","חשוב לציין",
          "במסגרת","על מנת","כמו כן","יש לציין","לאחרונה"]

def words(t):
    return len(t.split())

def find_dash(t):
    return ("—" in t) or ("–" in t)

def banned_hits(t):
    hits = []
    toks = re.findall(r"[֐-׿]+", t)
    for b in BANNED:
        if " " in b:
            if b in t:
                hits.append(b)
        else:
            if b in toks:
                hits.append(b)
    return hits

def collect_text(obj):
    parts = [obj["lead"]]
    for s in obj["sections"]:
        parts.append(s["h"]); parts.append(s["p"])
    parts += obj["specs"]
    for q,a in obj["faq"]:
        parts.append(q); parts.append(a)
    return parts

inp = json.load(open(INPUT_PATH, encoding="utf-8"))
names = [p["name"] for p in inp]

errors = []
for name in names:
    if name not in data:
        errors.append(f"MISSING PRODUCT: {name}")
        continue
    o = data[name]
    lw = words(o["lead"])
    if not (40 <= lw <= 60):
        errors.append(f"[{name}] lead words={lw}")
    if len(o["sections"]) != 3:
        errors.append(f"[{name}] sections count={len(o['sections'])}")
    for i,s in enumerate(o["sections"]):
        pw = words(s["p"])
        if not (134 <= pw <= 167):
            errors.append(f"[{name}] section{i} p words={pw}")
        if ":" in s["h"] or " - " in s["h"] or find_dash(s["h"]):
            errors.append(f"[{name}] section{i} heading has colon/dash: {s['h']}")
    if not (4 <= len(o["specs"]) <= 6):
        errors.append(f"[{name}] specs count={len(o['specs'])}")
    if len(o["faq"]) != 5:
        errors.append(f"[{name}] faq count={len(o['faq'])}")
    for t in collect_text(o):
        if find_dash(t):
            errors.append(f"[{name}] DASH in: {t[:40]}")
        bh = banned_hits(t)
        if bh:
            errors.append(f"[{name}] BANNED {bh} in: {t[:40]}")

extra = [k for k in data if k not in names]
if extra:
    errors.append(f"EXTRA KEYS: {extra}")

print(f"products in data: {len(data)} / expected {len(names)}")
if errors:
    print("VERIFY FAILED:")
    for e in errors:
        print("  -", e)
    sys.exit(1)
else:
    ordered = {name: data[name] for name in names}
    json.dump(ordered, open(OUTPUT_PATH,"w",encoding="utf-8"), ensure_ascii=False, indent=1)
    print("VERIFY OK — written to", OUTPUT_PATH)
